import React from 'react';

const FAQItem = ({ question, categoryName, onVote }) => {
  return (
    <div className="faq-item">
      <p>{question.question}</p>
      <div className="vote-buttons">
        <button onClick={() => onVote(categoryName, question.id, 1)}>Да</button>
        <button onClick={() => onVote(categoryName, question.id, -1)}>Нет</button>
        <span className="rating">Рейтинг: {question.rating}</span>
      </div>
    </div>
  );
};

export default FAQItem;
